import io


class MeteredFile(io.BufferedRandom):
    """Implement using a subclassing model."""

    def __init__(self, *args, **kwargs):
        # counters
        self._read_bytes = 0
        self._read_ops = 0
        self._write_bytes = 0
        self._write_ops = 0

        # Initialize BufferedRandom normally. Let exceptions propagate if initialization
        # is incorrect for the provided arguments.
        super().__init__(*args, **kwargs)

    def __enter__(self):
        # Do not delegate to underlying object's __enter__; return the wrapper itself.
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        # Prefer delegating to the raw object's __exit__ if available so it can suppress
        # exceptions. Otherwise try to call BufferedRandom's __exit__, but swallow any
        # errors that indicate the object wasn't fully initialized.
        raw = getattr(self, "raw", None)
        if raw is not None:
            exitm = getattr(raw, "__exit__", None)
            if callable(exitm):
                return exitm(exc_type, exc_val, exc_tb)
        try:
            return super().__exit__(exc_type, exc_val, exc_tb)
        except Exception:
            return False

    def __iter__(self):
        return self

    def __next__(self):
        # If we can access the raw object, use its readline to avoid double-counting
        # (since superclass readline may route through our read()).
        raw = getattr(self, "raw", None)
        if raw is not None:
            line = raw.readline()
            if not line:
                raise StopIteration
            self._read_ops += 1
            try:
                self._read_bytes += len(line)
            except Exception:
                pass
            return line
        # Fallback: use superclass readline. In this case, the read counting (if any)
        # will be handled by the read() override, so do not increment again here.
        line = super().readline()
        if not line:
            raise StopIteration
        return line

    def read(self, size=-1):
        data = super().read(size)
        # Count this read operation and bytes
        self._read_ops += 1
        if data:
            try:
                self._read_bytes += len(data)
            except Exception:
                pass
        return data

    @property
    def read_bytes(self):
        return self._read_bytes

    @property
    def read_ops(self):
        return self._read_ops

    def write(self, b):
        n = super().write(b)
        # Record bytes written; prefer returned count if available.
        try:
            if isinstance(n, int):
                self._write_bytes += n
            else:
                self._write_bytes += len(b)
        except Exception:
            pass
        self._write_ops += 1
        return n

    @property
    def write_bytes(self):
        return self._write_bytes

    @property
    def write_ops(self):
        return self._write_ops


